import re

def extract_level(line: str) -> str | None:
    """Extracts the log level (INFO, ERROR, WARN, DEBUG) from a line."""
    pattern = r'\b(INFO|ERROR|WARN|DEBUG)\b'
    match = re.search(pattern, line)

    if match:
        return match.group(1)
    else:
        return None
