def flatten(d: dict) -> dict:
    result = {}

    for key, value in d.items():
        if isinstance(value, dict):
            # Recursively process nested dicts and join keys with a dot
            flattened_value = {f"{key}.{sub_key}": sub_val 
                               for sub_key, sub_val in flatten(value).items()}
            result.update(flattened_value)
        else:
            # Non-dict values stay as they are (just use the key directly)
            result[key] = value

    return result
